279	    /**
280	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
281	     * contained in {@code value}. Reading the digits right to left, every second one is
282	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
283	     * digits are summed, and the check digit is the amount that must be added to that sum to
284	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
285	     * the digit is taken over exactly the digits the string carries.
286	     */
287	    private static int luhnCheckDigit(String value) {
288	        int sum = 0;
289	        boolean doubling = true;
290	        for (int i = value.length() - 1; i >= 0; i--) {
291	            char c = value.charAt(i);
292	            if (c < '0' || c > '9') {
293	                continue;
294	            }
295	            int digit = c - '0';
296	            if (doubling) {
297	                digit *= 2;
298	                if (digit > 9) {
299	                    digit -= 9;
300	                }
301	            }
302	            sum += digit;
303	            doubling = !doubling;
304	        }
305	        return (10 - (sum % 10)) % 10;
306	    }
