308	    /** Fixed city-to-region table used to derive an owner's locality. */
309	    private static final Map<String, String> CITY_REGION = Map.of(
310	        "Sydney", "NSW",
311	        "Melbourne", "VIC",
312	        "Brisbane", "QLD");
313	
314	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
315	    public static final String UNKNOWN_REGION = "UNKNOWN";
316	
317	    /**
318	     * The canonical region for a city, derived from the fixed city-to-region table
319	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
320	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
321	     * source of the city-to-region mapping, shared by every rule that is keyed by
322	     * region so the mapping is never re-derived elsewhere.
323	     */
324	    public static String regionOf(String city) {
325	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
326	    }
