328	    /**
329	     * The owner's locality: the {@code <REGION>} component of the {@link #getCustomerCode()
330	     * customerCode} (its prefix up to the first {@code '-'}), which is the region derived from
331	     * the owner's postcode at creation ({@link #UNKNOWN_REGION} when the postcode maps to no
332	     * known region). Locality is read from the region-and-hash identity so it never re-derives
333	     * a region of its own; it is {@link #UNKNOWN_REGION} for an owner that has no customerCode.
334	     */
335	    public String getLocality() {
336	        if (this.customerCode == null) {
337	            return UNKNOWN_REGION;
338	        }
339	        int dash = this.customerCode.indexOf('-');
340	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
341	    }
