343	    /** Fixed region-to-timezone table, mapping a region to its IANA timezone name. */
344	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
345	        "NSW", "Australia/Sydney",
346	        "VIC", "Australia/Melbourne",
347	        "QLD", "Australia/Brisbane");
348	
349	    /**
350	     * The owner's timezone: the IANA name for this owner's {@linkplain #getLocality() locality},
351	     * looked up in the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
352	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null} when
353	     * the locality maps to no known region (e.g. {@link #UNKNOWN_REGION}). It reads the locality
354	     * rather than re-deriving a region so the timezone shares the owner's single region identity.
355	     */
356	    public String getTimezone() {
357	        return REGION_TIMEZONE.get(getLocality());
358	    }
