372	    /**
373	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
374	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
375	     * no known range.
376	     */
377	    private static String regionOfPostcode(String postcode) {
378	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
379	            return null;
380	        }
381	        int value = Integer.parseInt(postcode);
382	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
383	            int[] range = entry.getValue();
384	            if (value >= range[0] && value <= range[1]) {
385	                return entry.getKey();
386	            }
387	        }
388	        return null;
389	    }
390	
391	    /**
392	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
393	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
394	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
395	     */
396	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
397	        "NSW", new int[] {2000, 2099},
398	        "VIC", new int[] {3000, 3099},
399	        "QLD", new int[] {4000, 4099});
400	
401	    /**
402	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
403	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
404	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
405	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
406	     * city with no known region accepts any 4-digit postcode.
407	     */
408	    public boolean isPostcodeValid() {
409	        if (this.postcode == null) {
410	            return true;
411	        }
412	        if (!this.postcode.matches("[0-9]{4}")) {
413	            return false;
414	        }
415	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
416	        if (range == null) {
417	            return true;
418	        }
419	        int value = Integer.parseInt(this.postcode);
420	        return value >= range[0] && value <= range[1];
421	    }
