423	    /**
424	     * The national (subscriber) digit count required by each known country calling code, keyed by
425	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
426	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
427	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
428	     * re-derived elsewhere.
429	     */
430	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
431	        "1", 10,
432	        "61", 9);
433	
434	    /**
435	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
436	     * E.164 digit string, choosing the longest matching code known to
437	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
438	     * country code. This is the single place a country code is read from an E.164 number, so every
439	     * rule keyed by that code shares one derivation.
440	     */
441	    private static String countryCodeOf(String e164Digits) {
442	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
443	            .filter(e164Digits::startsWith)
444	            .max(Comparator.comparingInt(String::length))
445	            .orElse(null);
446	    }
447	
448	    /**
449	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
450	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
451	     * known code wins; a number whose country code is not recognised passes this check (its length is
452	     * then governed only by the general E.164 bound), while a recognised code must be followed by
453	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
454	     */
455	    public static boolean hasValidNationalLength(String e164Digits) {
456	        String countryCode = countryCodeOf(e164Digits);
457	        if (countryCode == null) {
458	            return true;
459	        }
460	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
461	    }
462	
463	    /**
464	     * The owner's membership points: they start at 0, gain 2 when an email is present, gain 1 when
465	     * namesakeCount is 0, gain 2 for a {@linkplain #hasLargeHousehold() household of 3 or more}, and
466	     * gain 3 when the owner's {@linkplain #getTenureDays() tenure} exceeds 365 days. The email,
467	     * namesake and household factors are available on creation; the tenure factor is reached only
468	     * once tenure grows beyond 365 days.
469	     */
470	    public Integer getMembershipPoints() {
471	        int points = 0;
472	        if (hasEmail()) {
473	            points += 2;
474	        }
475	        if (hasNoNamesakes()) {
476	            points += 1;
477	        }
478	        if (hasLargeHousehold()) {
479	            points += 2;
480	        }
481	        if (hasTenureBeyondOneYear()) {
482	            points += 3;
483	        }
484	        return points;
485	    }
486	
487	    /**
488	     * The owner's membership level, a number from 1 to 4 derived from {@linkplain #getMembershipPoints()
489	     * membershipPoints}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or
490	     * more.
491	     */
492	    public Integer getMembershipLevel() {
493	        int points = getMembershipPoints();
494	        if (points >= 6) {
495	            return 4;
496	        }
497	        if (points >= 4) {
498	            return 3;
499	        }
500	        if (points >= 2) {
501	            return 2;
502	        }
503	        return 1;
504	    }
505	
506	    /**
507	     * Whether this owner belongs to a household of three or more: its {@link #getHouseholdSize()
508	     * householdSize} is {@code 3} or greater. A {@code null} householdSize, meaning the size is not
509	     * known, is treated as not a large household.
510	     */
511	    private boolean hasLargeHousehold() {
512	        return this.householdSize != null && this.householdSize >= 3;
513	    }
514	
515	    /**
516	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
517	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
518	     * email presence so the check is never re-derived elsewhere.
519	     */
520	    private boolean hasEmail() {
521	        return this.email != null && !this.email.isEmpty();
522	    }
523	
524	    /**
525	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
526	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
527	     * not known, is treated as not unique.
528	     */
529	    private boolean hasNoNamesakes() {
530	        return this.namesakeCount != null && this.namesakeCount == 0;
531	    }
532	
533	    /**
534	     * Whether this owner's {@linkplain #getTenureDays() tenure} exceeds 365 days. A newly created owner
535	     * (zero tenure) does not qualify; the threshold is crossed only once tenure grows beyond one year.
536	     */
537	    private boolean hasTenureBeyondOneYear() {
538	        return this.getTenureDays() > 365;
539	    }
540	
541	    /**
542	     * The owner's tenure in whole days: the number of days between the {@link #registrationDate} and
543	     * the current date, or {@code 0} when the registrationDate is not yet set (a newly created owner has
544	     * zero tenure). Never negative.
545	     */
546	    public long getTenureDays() {
547	        if (this.registrationDate == null) {
548	            return 0;
549	        }
550	        return Math.max(0, ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()));
551	    }
552	
553	    /**
554	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
555	     * otherwise {@code 'PHONE'}.
556	     */
557	    public String getContactPreference() {
558	        return hasEmail() ? "EMAIL" : "PHONE";
559	    }
560	
561	    /**
562	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
563	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
564	     * the national digits grouped into threes from the left separated by spaces,
565	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
566	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
567	     * E.164 form, or carries no known country code.
568	     */
569	    public String getTelephoneDisplay() {
570	        if (this.telephone == null || !this.telephone.startsWith("+")) {
571	            return this.telephone;
572	        }
573	        String digits = this.telephone.substring(1);
574	        String countryCode = countryCodeOf(digits);
575	        if (countryCode == null) {
576	            return this.telephone;
577	        }
578	        String national = digits.substring(countryCode.length());
579	        StringBuilder groups = new StringBuilder();
580	        for (int i = 0; i < national.length(); i += 3) {
581	            if (groups.length() > 0) {
582	                groups.append(' ');
583	            }
584	            groups.append(national, i, Math.min(i + 3, national.length()));
585	        }
586	        return "+" + countryCode + " " + groups;
587	    }
588	
589	    /**
590	     * The owner's identity key: the single derived value used for duplicate detection.
591	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
592	     * empty string when absent) and the householdId (or the empty string when the owner
593	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
594	     * Two owners are duplicates only when their whole identity keys are equal.
595	     */
596	    public String getIdentityKey() {
597	        String telephonePart = this.telephone == null ? "" : this.telephone;
598	        String emailPart = this.email == null ? "" : this.email;
599	        String householdPart = this.householdId == null ? "" : this.householdId;
600	        return telephonePart + "|" + emailPart + "|" + householdPart;
601	    }
602	
603	    protected Set<Pet> getPetsInternal() {
604	        if (this.pets == null) {
605	            this.pets = new HashSet<>();
606	        }
607	        return this.pets;
608	    }
609	
610	    protected void setPetsInternal(Set<Pet> pets) {
611	        this.pets = pets;
612	    }
613	
614	    public List<Pet> getPets() {
615	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
616	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
617	        return Collections.unmodifiableList(sortedPets);
618	    }
619	
620	    public void setPets(List<Pet> pets) {
621	        this.pets = new HashSet<>(pets);
622	    }
623	
624	    public void addPet(Pet pet) {
625	        getPetsInternal().add(pet);
626	        pet.setOwner(this);
627	    }
628	
629	    /**
630	     * Return the Pet with the given name, or null if none found for this Owner.
631	     *
632	     * @param name to test
633	     * @return true if pet name is already in use
634	     */
635	    public Pet getPet(String name) {
636	        return getPet(name, false);
637	    }
638	
639	    /**
640	     * Return the Pet with the given name, or null if none found for this Owner.
641	     *
642	     * @param name to test
643	     * @return true if pet name is already in use
644	     */
645	    public Pet getPet(String name, boolean ignoreNew) {
646	        name = name.toLowerCase();
647	        for (Pet pet : getPetsInternal()) {
648	            if (!ignoreNew || !pet.isNew()) {
649	                String compName = pet.getName();
650	                compName = compName.toLowerCase();
651	                if (compName.equals(name)) {
652	                    return pet;
653	                }
654	            }
655	        }
656	        return null;
657	    }
658	
659	    public Pet getPet(Integer petId) {
660	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
661	    }
662	
663	    @Override
664	    public String toString() {
665	        return new ToStringCreator(this)
666	
667	            .append("id", this.getId())
668	            .append("new", this.isNew())
669	            .append("lastName", this.getLastName())
670	            .append("firstName", this.getFirstName())
671	            .append("address", this.address)
672	            .append("city", this.city)
673	            .append("telephone", this.telephone)
674	            .append("email", this.email)
675	            .toString();
676	    }
677	}
